      patterns: /consumer packaged goods|packaged goods|brand assortment|retail shelf|retail pack|case pack|promotion|merchandising|grocery/i,
      evidence: 'website/category tokens show retail packaged goods or promotion signals',
      product: 'Retail Packaged Goods Assortment',
