      custpage_enablemfg: toTf(buildPacket.dccRunnerInputs.enableManufacturing),
      custpage_enablewip: toTf(buildPacket.dccRunnerInputs.enableWip),
      custpage_evalmode: 'review_only',
      custpage_actionmode: confirmed ? '' : 'previewbrief'
