        stateAuthorityAndHandoffParityPreserved: true,
        idempotencyPreserved: true,
        internalRunnerOwnership: true,
        rollbackByDisablingServerFlags: true,
        pendingAndAdapterErrorNoMutationPreserved: !!(opts.pendingAndAdapterErrorNoMutationPreserved !== false),
        noActiveOpenLinksWithoutRealUrls: byRole.every((record) => !record.openable || record.supportedUrl)
