  function w213ProofObjectName(state, lane, pageContext, recommendation) {
    const finalNavigation = dccFinalNavigationModel(state, lane, pageContext, recommendation);
    if (finalNavigation && finalNavigation.runCanUseImportedFinalNames) {
      const proofItem = finalNavigation.scriptPivotObjects.find((item) => /matrix|proof|hero/i.test(item.label || '')) || finalNavigation.scriptPivotObjects[0];
      if (proofItem && proofItem.name) return proofItem.name;
    }
    return lane && lane.proofAnchor ? lane.proofAnchor : 'the NetSuite proof path';
  }

  function consultantStoryRoiCompetitiveQualityPassW213V1(state, lane, pageContext, recommendation, options) {
    const opts = options || {};
    const intake = normalizedIntake(state);
    const orchestration = websiteGroundedStoryRoiCompetitiveNamingOrchestrationW212V1(state, lane, pageContext, recommendation, opts);
    const modeKey = orchestration.layers.toggleAwareOperatingModel.modeKey;
    const rules = w213ModeCoachingRules(modeKey);
    const websiteLayer = orchestration.layers.websiteCategoryEvidence;
    const productSeed = firstNonBlank(websiteLayer.productSeed, websiteLayer.productFamily, lane && lane.proofAnchor, 'the product path');
    const customer = customerSeed(intake.customer);
    const notesDigest = consultantNotesDigestV1(state, lane, websiteProductNamingEvidence(state, lane));
    const notesPain = intake.notes
      ? notesDigest.pain
      : `The buyer needs confidence in ${rules.storyAnchor} before the next operating decision.`;
    const proofObject = w213ProofObjectName(state, lane, pageContext, recommendation);
    const decision = `Use ${proofObject} to help ${customer} trust ${rules.storyAnchor} inside NetSuite.`;
    const copyModel = {
      schema: 'idb.w213-consultant-copy-model.v1',
      talkTrack: `${notesDigest.talkTrack} Position NetSuite as the operating system for ${rules.storyAnchor}.`,
      discoveryQuestion: rules.roiQuestion,
      proofMove: `${notesDigest.proof} Use ${proofObject} and keep the proof in NetSuite, not in a detached feature tour.`,
      roiAnswer: `Frame ROI as risk reduction first: protect the ${rules.storyAnchor} decision, capture the current baseline before claiming savings, then quantify fewer misses, delays, exposure, or manual touches only after the buyer confirms that baseline.`,
      competitiveAnswer: rules.competitiveContrast,
      objectionAnswer: rules.objectionPattern,
      closeValue: `Confirm the decision owner, the baseline to capture, and whether ${customer} can trust the NetSuite path for ${rules.storyAnchor}.`,
      runCoaching: {
        open: {
          title: 'Open on the buyer risk',
          say: notesDigest.runOpen,
          show: `Start from ${proofObject}; ${rules.proofMoment}.`,
          close: rules.roiQuestion
        },
        prove: {
          title: 'Prove the NetSuite path',
          say: `${notesDigest.runProve} Tie it back to ${notesPain} and show that NetSuite keeps the operating decision in one path.`,
          show: `Move through the live Customer, Sales Order, and item records that support ${rules.storyAnchor}.`,
          close: `Ask whether this proof gives ${customer} enough trust to make the next decision without manual reconciliation.`
        },
        handle_objection: {
          title: 'Handle the buying doubt',
          say: rules.objectionPattern,
          show: `Return to ${proofObject}, then compare the current workflow against the NetSuite path without making unsupported competitor claims.`,
          close: `Ask what would still make ${rules.storyAnchor} untrusted after seeing the NetSuite proof.`
        },
        close_value: {
          title: 'Close on financial impact',
          say: `Summarize the decision ${customer} can now make: ${decision}. Capture the baseline before claiming savings.`,
          show: `Use the final generated records to connect ${rules.storyAnchor} to order promise and financial impact.`,
          close: `Confirm owner, timing, baseline, and next step.`
        }
      }
    };
    return {
      schema: 'idb.w213-consultant-story-roi-competitive-quality-pass.v1',
      status: 'consultant_story_roi_competitive_ready',
      orchestrationBaseline: orchestration.schema,
      layers: orchestration.layers,
      storyRoiCompetitiveCoachingContract: {
        websiteAnchorsIndustryAndProductContext: true,
        notesShapePainRoiCompetitiveAndObjectionsOnly: true,
        netSuitePositionedAsWinningOperatingSystem: true,
        noUnsupportedIndustryClaims: true,
        noMeasuredSavingsWithoutBaseline: true,
        nllmAdvisoryOnly: true
      },
      updatedConsultantCopyModel: copyModel,
      noRegression: orchestration.noRegression
    };
  }

