  function dccFinalNavigationModel(state, lane, pageContext, recommendation) {
    const finalResult = dccFinalNamingResultV1(state && state.dccFinalNamingResult, state, lane, pageContext, recommendation);
    const packet = dryRunObjectPacket(state, lane, pageContext, recommendation);
    const finalObjects = finalResult.finalNamesImported
      ? finalResult.displayObjects.concat(finalResult.componentItems, finalResult.locationPlanningRecords).filter((item) => item.source === 'dcc_final')
      : [];
    const provisionalObjects = packet.records.map((record) => {
      const preview = record.preview || buildEnrichedObjectPreview(state, lane, record);
      return {
        role: record.role,
        label: record.label,
        name: preview.proposedName || record.plannedName,
        id: '',
        url: '',
        source: 'idb_provisional_preview'
      };
    });
    const activeObjects = (finalObjects.length ? finalObjects : provisionalObjects).map(applyRecordLinkAuthority);
    const linkAuthoritySummary = activeObjects.reduce((summary, item) => {
      const status = item.linkAuthority && item.linkAuthority.status ? item.linkAuthority.status : 'unknown';
      summary[status] = (summary[status] || 0) + 1;
      return summary;
    }, {});
    const scriptPivotObjects = finalObjects.length
      ? activeObjects.filter((item) => item && item.linkAuthority && item.linkAuthority.openable === true)
      : activeObjects.slice(0, 4);
    return {
      schema: 'idb.dcc-final-navigation-model.v1',
      status: finalObjects.length ? 'using_dcc_final_names' : 'using_provisional_preview_names',
      displayStatus: finalObjects.length ? 'Final generated names imported' : 'Final generated names not imported yet',
      source: finalObjects.length ? 'dcc_final_imported' : 'idb_provisional_preview',
      runCanUseImportedFinalNames: finalObjects.length > 0,
      reviewObjects: activeObjects.slice(0, 6),
      scriptPivotObjects,
      linkAuthoritySummary,
      warnings: finalResult.warnings,
      w240NoDropGuard: {
        schema: 'forge.w240-run-pivot-no-drop-guard.v1',
        finalImportedRecordCount: finalObjects.length,
        openableRunPivotCount: scriptPivotObjects.length,
        fixedFourRecordSliceApplied: finalObjects.length ? false : true,
        allOpenableFinalRecordsIncluded: finalObjects.length
          ? scriptPivotObjects.length === activeObjects.filter((item) => item && item.linkAuthority && item.linkAuthority.openable === true).length
          : true
      },
      noRegression: {
        provisionalNamesCannotBeMarkedFinal: !finalObjects.length,
        noIdbWrites: true,
        noSuiteScriptInvocationFromIdb: true,
        noTransactionWritesFromIdb: true,
        dccOwnsObjectGeneration: true
      }
    };
  }

