  function finalGeneratedNamesNavigationIntegrationV1(input, state, lane, pageContext, recommendation) {
    const source = input && input.finalGeneratedNamesJson ? input.finalGeneratedNamesJson : input;
    const importedFinalNaming = dccFinalNamingResultV1(source, state, lane, pageContext, recommendation);
    const importedState = Object.assign({}, state || {}, { dccFinalNamingResult: importedFinalNaming });
    const navigation = dccFinalNavigationModel(importedState, lane, pageContext, recommendation);
    const objects = navigation.reviewObjects.concat(navigation.scriptPivotObjects);
    const objectByRole = (role) => objects.find((item) => item && item.role === role);
    const componentObjects = importedFinalNaming.componentItems.filter((item) => item && item.source === 'dcc_final');
    const requiredRoles = ['customer', 'sales_order', 'hero_item', 'matrix_or_proof_item'];
    const roleChecks = requiredRoles.map((role) => {
      const object = objectByRole(role);
      return {
        role,
        present: !!(object && object.name),
        hasLink: !!(object && object.url),
        openable: !!(object && object.linkAuthority && object.linkAuthority.openable),
        name: object && object.name ? object.name : '',
        url: object && object.url ? object.url : ''
      };
    });
    const componentChecks = componentObjects.map((object) => ({
      role: 'component_item',
      present: !!object.name,
      hasLink: !!object.url,
      openable: !!(object.linkAuthority && object.linkAuthority.openable),
      name: object.name || '',
      url: object.url || ''
    }));
    const buildUsesImportedNames = navigation.status === 'using_dcc_final_names'
      && navigation.reviewObjects.some((item) => item.role === 'customer' && item.name === roleChecks.find((check) => check.role === 'customer').name)
      && navigation.reviewObjects.some((item) => item.role === 'sales_order')
      && navigation.reviewObjects.some((item) => item.role === 'hero_item')
      && navigation.reviewObjects.some((item) => item.role === 'matrix_or_proof_item');
    const runUsesImportedNames = navigation.runCanUseImportedFinalNames === true
      && navigation.scriptPivotObjects.some((item) => item.role === 'customer')
      && navigation.scriptPivotObjects.some((item) => item.role === 'sales_order')
      && navigation.scriptPivotObjects.some((item) => item.role === 'hero_item')
      && navigation.scriptPivotObjects.some((item) => item.role === 'matrix_or_proof_item');
    const linkChecks = roleChecks.concat(componentChecks);
    return {
      schema: 'idb.w130-final-generated-names-navigation-integration.v1',
      status: buildUsesImportedNames && runUsesImportedNames && linkChecks.every((check) => check.present && check.hasLink)
        ? 'final_generated_names_navigation_integrated'
        : 'final_generated_names_navigation_incomplete',
      source: 'w129_operator_only_sandbox_preview_result_json',
      importTarget: 'state.dccFinalNamingResult',
      importMode: 'result_json_only_no_write',
      finalNamesImported: importedFinalNaming.finalNamesImported === true,
      buildUsesImportedNames,
      runUsesImportedNames,
      buildNavigationObjects: navigation.reviewObjects,
      runNavigationPivots: navigation.scriptPivotObjects,
      requiredRoleChecks: roleChecks,
      componentItemChecks: componentChecks,
      warnings: importedFinalNaming.warnings || [],
      errors: importedFinalNaming.errors || [],
      recoverableBlockers: importedFinalNaming.recoverableBlockers || [],
      rollback: {
        noSubmitBehavior: 'If import fails, clear imported names and keep provisional names non-final.',
        drawerRollbackAction: 'Clear browser-local imported names only; do not alter NetSuite records.',
        netSuiteRecordRollbackAction: 'none_from_drawer',
        rejectedResultBehavior: 'Import nothing and keep Build/Run on provisional navigation.'
      },
      noRegression: {
        noDrawerWrites: true,
        noSuiteScriptInvocationFromDrawer: true,
        noTransactionWritesFromDrawer: true,
        consultantConfirmationRequired: true,
        stateAuthorityPreserved: true,
        handoffParityPreserved: true,
        noSubmitRollbackPreserved: true,
        generatedRecordsOwnedByInternalBuildEngine: true,
        importOnly: true
      }
    };
  }

  function finalGeneratedNamesOperatorCopyNavigationQaV1(input, state, lane, pageContext, recommendation) {
    const integration = finalGeneratedNamesNavigationIntegrationV1(input, state, lane, pageContext, recommendation);
    const allObjects = integration.buildNavigationObjects
      .concat(integration.runNavigationPivots)
      .filter((item) => item && item.source === 'dcc_final');
    const uniqueByRoleAndUrl = [];
    allObjects.forEach((item) => {
      const key = `${item.role || item.label || ''}|${item.url || item.id || item.name || ''}`;
      if (!uniqueByRoleAndUrl.some((existing) => existing.key === key)) {
        uniqueByRoleAndUrl.push({ key, item });
      }
    });
    const snippets = uniqueByRoleAndUrl.map(({ item }) => ({
      role: item.role || 'record',
      label: item.label || 'Record',
      name: item.name || '',
      id: item.id || '',
      url: item.url || '',
      copyText: `${item.label || 'Record'}: ${item.name || 'Name not returned'}${item.openableUrl ? `\n${item.openableUrl}` : ''}`,
      consultantUsable: !!item.name,
      linkAuthority: item.linkAuthority || verifiedRecordLinkAuthorityV1(item),
      opensFromDrawerOnlyAsLink: !!(item.linkAuthority && item.linkAuthority.openable)
    }));
    const requiredLabels = ['Customer', 'Sales Order / demo transaction', 'Hero item', 'Matrix item / proof item'];
    const visibleSmokeChecklist = [
      'Build Results shows final generated names imported.',
      'Build Results shows Customer, demo transaction, hero item, and matrix/proof item names.',
      'Build Results exposes Open links only, not submit or write controls.',
      'Run shows Use final build names.',
      'Run shows Customer, demo transaction, hero item, and matrix/proof item names.',
      'Run exposes Open links for final generated records.',
      'Component copy snippet is present for operator handoff.',
      'No drawer write, SuiteScript invocation, queue, submit, or transaction write control appears.'
    ];
    return {
      schema: 'idb.w131-final-generated-names-operator-copy-navigation-qa.v1',
      status: snippets.every((snippet) => snippet.consultantUsable) && requiredLabels.every((label) => snippets.some((snippet) => snippet.label === label))
        ? 'operator_copy_navigation_qa_ready'
        : 'operator_copy_navigation_qa_incomplete',
      source: 'w130_final_generated_names_navigation_model',
      copyMode: 'copy_safe_names_and_urls_only',
      snippets,
      visibleSmokeChecklist,
      buildSmoke: {
        usesImportedFinalNames: integration.buildUsesImportedNames,
        hasOpenLinks: integration.requiredRoleChecks.every((check) => check.hasLink)
      },
      runSmoke: {
        usesImportedFinalNames: integration.runUsesImportedNames,
        hasOpenLinks: integration.runNavigationPivots.every((item) => !!item.url)
      },
      rollback: integration.rollback,
      noRegression: {
        noDrawerWrites: true,
        noSuiteScriptInvocationFromDrawer: true,
        noTransactionWritesFromDrawer: true,
        consultantConfirmationRequired: true,
        stateAuthorityPreserved: true,
        handoffParityPreserved: true,
        noSubmitRollbackPreserved: true,
        generatedRecordsOwnedByInternalBuildEngine: true,
        copyOnly: true
      }
    };
  }

