    const lane = getLane(state);
    const pageContext = currentPageContext();
    const recommendation = recommendMove(lane, pageContext);
    const payload = dccRunnerHandoffPacketV1(state, lane, pageContext, recommendation);
    const operatorApproval = dccOperatorApprovalModelV1(state, lane, pageContext, recommendation, { handoffExportedOverride: true });
    const sandboxPreviewBridge = dccSandboxPreviewBridgeV1(state, lane, pageContext, recommendation, { handoffExportedOverride: true });
    const previewUrlOperatorCopy = dccPreviewUrlOperatorCopyV1(state, lane, pageContext, recommendation, { handoffExportedOverride: true });
    const operatorEvidenceIntake = operatorApprovalEvidenceIntakeV1(state, lane, pageContext, recommendation, { handoffExportedOverride: true });
    const invocationReadiness = dccInvocationReadinessV1(state, lane, pageContext, recommendation, { handoffExportedOverride: true });
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
